// @ts-nocheck
/**
 * archetype-compatibility.js — Personality Relationship System
 * Shows how archetypes interact, attract, and challenge each other.
 */

var ARCHETYPE_COMPATIBILITY = {

    // World-level compatibility patterns
    worlds: {
        'dreamers-dreamers': {
            zh: { name: '深海共鸣', desc: '你们会在沉默中理解彼此，不需要语言。但要注意：两个人都退缩时，没有人会主动靠近。', tension: '你们都习惯等待对方先开口。' },
            en: { name: 'Deep Sea Resonance', desc: 'You understand each other in silence, no words needed. But beware: when both retreat, no one moves closer.', tension: 'You both habitually wait for the other to speak first.' }
        },
        'dreamers-analysts': {
            zh: { name: '月光与蓝图', desc: '你负责感受，对方负责结构。你们会互相不理解，但也因此互相吸引。', tension: '你觉得对方太冷，对方觉得你太飘。' },
            en: { name: 'Moonlight and Blueprints', desc: 'You handle feeling, they handle structure. You will misunderstand each other, and that is exactly why you are drawn together.', tension: 'You think they are too cold; they think you are too ungrounded.' }
        },
        'dreamers-connectors': {
            zh: { name: '潮汐与港湾', desc: '你需要一个安全的地方来释放情绪，对方正好是那个地方。但小心：对方可能会被你的情绪淹没。', tension: '你的深度有时会让对方感到沉重。' },
            en: { name: 'Tide and Harbor', desc: 'You need a safe place to release emotions, and they are exactly that place. But be careful: they may be overwhelmed by your depth.', tension: 'Your depth can sometimes feel heavy to them.' }
        },
        'dreamers-explorers': {
            zh: { name: '月光与篝火', desc: '你安静，对方热烈。你会被对方的活力吸引，对方会被你的深度吸引。但你们需要学会在不同的节奏中找到共同的节拍。', tension: '你想要安静，对方想要行动。' },
            en: { name: 'Moonlight and Campfire', desc: 'You are quiet, they are vivid. You are drawn to their energy; they are drawn to your depth. But you need to find a shared rhythm in different tempos.', tension: 'You want silence; they want action.' }
        },
        'analysts-analysts': {
            zh: { name: '双塔对望', desc: '你们互相尊重，互相竞争，也互相孤独。两个建筑师之间，最难的是承认自己也需要被照顾。', tension: '你们都习惯独立，会忘记连接。' },
            en: { name: 'Twin Towers', desc: 'You respect each other, compete with each other, and are lonely together. Between two architects, the hardest thing is admitting you need to be taken care of.', tension: 'You are both used to independence and forget to connect.' }
        },
        'analysts-connectors': {
            zh: { name: '铁架与藤蔓', desc: '你提供结构，对方提供温度。你们会互补，但也需要学会说"我需要你"而不是"我分析了你"。', tension: '你会用逻辑分析对方的情绪，而不是感受它。' },
            en: { name: 'Frame and Vine', desc: 'You provide structure, they provide warmth. You complement each other, but need to learn to say "I need you" instead of "I analyzed you."', tension: 'You analyze their emotions instead of feeling them.' }
        },
        'analysts-explorers': {
            zh: { name: '棋盘与赛道', desc: '你喜欢计划，对方喜欢即兴。你们会互相烦躁，但也会互相补全——你教对方思考，对方教你行动。', tension: '你觉得对方太冲动，对方觉得你太慢。' },
            en: { name: 'Chessboard and Racetrack', desc: 'You like planning, they like improvising. You will irritate each other, but also complete each other — you teach them to think, they teach you to act.', tension: 'You think they are too impulsive; they think you are too slow.' }
        },
        'connectors-connectors': {
            zh: { name: '双镜互照', desc: '你们会把对方照顾得很好，但也会忘记自己。两个给予者之间，最需要学会的是接受。', tension: '你们都在给予，没有人允许自己接受。' },
            en: { name: 'Mirrors Facing', desc: 'You will take care of each other beautifully, but also forget yourselves. Between two givers, the hardest thing is learning to receive.', tension: 'You are both giving, and neither allows themselves to receive.' }
        },
        'connectors-explorers': {
            zh: { name: '港湾与帆船', desc: '你想要稳定，对方想要自由。但你会成为对方回来的理由，对方会成为你出发的勇气。', tension: '你害怕对方走远，对方害怕被困住。' },
            en: { name: 'Harbor and Sailboat', desc: 'You want stability, they want freedom. But you become their reason to return, and they become your courage to depart.', tension: 'You fear they will drift away; they fear being trapped.' }
        },
        'explorers-explorers': {
            zh: { name: '双风并行', desc: '你们一起会很快，但也会一起迷路。两个行动者之间，最难的是学会停下来。', tension: '你们都在往前冲，没有人回头看。' },
            en: { name: 'Twin Winds', desc: 'You will move fast together, but also get lost together. Between two doers, the hardest thing is learning to stop.', tension: 'You both charge forward, and neither looks back.' }
        }
    },

    // Specific archetype pairings (cinematic descriptions)
    pairs: {
        'INFP-INFJ': {
            zh: { name: '夜航者 × 星图解读者', desc: '你们会在深夜的对话中发现：原来有人和你一样，在安静中感受整个世界。你们的连接不需要解释，但需要有人先开口。', quote: '你们都习惯在沉默中理解一切，但这段关系需要一个先开口的人。', how_they_meet: '在一家快要关门的书店里，你们同时伸手去拿同一本旧诗集。或者是一个只有七个人的深夜读书会，你们坐在对角，却一直在偷看同一个段落。', emotional_cycle: 'INFP退进自己的海里，INFJ在岸边点一盏小灯。INFP浮出水面的时候，发现INFJ从来没有离开过。然后INFP又会因为太靠近而害怕，再次潜下去。', conflict_source: 'INFP觉得INFJ在"管理"自己的情绪，而不是真正感受它。INFJ觉得INFP把所有的情绪都变成了关于自己的故事，而忽略了更大的图景。', who_retreats_first: 'INFP。他们不是生气，是需要回到自己的世界里确认自己还是自己。INFJ会等，但等待的方式是安静地做自己的事，这让INFP更不敢回来。', who_softens_first: 'INFJ。他们会在第三天发一条很短的消息，不是道歉，只是分享一个和你们上次对话有关的东西。INFP看到那条消息的时候，就知道门没有关上。', most_dangerous_phase: '当INFP开始把INFJ的沉默解读为"你不在乎我"，而INFJ把INFP的退缩解读为"你在惩罚我"。两个人都在等对方证明爱，但谁也不开口。', deepest_connection: '凌晨三点，两个人都没睡，INFP突然说出一个从来没有告诉过任何人的想法。INFJ没有回应"我理解"，只是说"我也是"。那一刻你们之间没有任何距离。', night_state_together: '各占沙发的一端，一个人在写东西，一个人在看书。偶尔INFP会念一句刚写的句子，INFJ不用抬头就能给出一个精准的回应。房间里只有翻页声和键盘声。', after_separation: 'INFP会在某个下雨天突然想起INFJ说过的一句话，然后意识到那句话在很久以前就改变了自己看世界的方式。INFJ则会在整理旧笔记时发现，很多自己以为是自己的想法，其实最早是INFP说的。' },
            en: { name: 'Night Sailor × Star Reader', desc: 'You will discover in a late-night conversation: someone else feels the whole world in silence, just like you. Your connection needs no explanation, but it does need someone to speak first.', quote: 'You both understand everything in silence, but this relationship needs someone to speak first.', how_they_meet: 'A bookshop about to close, both reaching for the same worn poetry collection. Or a tiny late-night reading group with seven people — you sit at opposite corners but keep glancing at the same passage.', emotional_cycle: 'The INFP drifts back into their sea; the INFJ lights a small lantern on the shore. When the INFP surfaces, they find the INFJ never left. Then the INFP panics from the closeness and dives again.', conflict_source: 'The INFP feels the INFJ is managing their emotions rather than actually feeling them. The INFP feels the INFJ turns every feeling into a story about themselves while ignoring the bigger picture.', who_retreats_first: 'The INFP. They are not angry — they need to return to their own world to confirm they are still themselves. The INFJ will wait, but their way of waiting is quietly going about their own business, which makes the INFP even more afraid to come back.', who_softens_first: 'The INFJ. On the third day they send a short message — not an apology, just something that connects to your last conversation. When the INFP sees it, they know the door was never closed.', most_dangerous_phase: 'When the INFP starts reading the INFJ\'s silence as "you don\'t care about me," and the INFJ reads the INFP\'s withdrawal as "you are punishing me." Both are waiting for the other to prove love, but neither speaks.', deepest_connection: 'Three in the morning, neither asleep, and the INFP suddenly says something they have never told anyone. The INFJ does not respond with "I understand" — they just say "me too." In that moment there is no distance between you.', night_state_together: 'Each end of the couch — one writing, one reading. Occasionally the INFP reads aloud a line they just typed, and the INFJ answers precisely without looking up. The room holds only the sound of turning pages and tapping keys.', after_separation: 'The INFP will hear rain on some random afternoon and realize something the INFJ once said changed how they see the world, long before they noticed. The INFJ, sorting old notes, will discover that many ideas they thought were their own actually started as something the INFP said.' }
        },
        'INFP-ENFJ': {
            zh: { name: '夜航者 × 灯塔守望者', desc: '你需要被看见，对方能看见你。但你要小心：对方的光太强时，你会想躲回自己的海里。', quote: '对方是你的灯塔，但你不需要一直被照亮。', how_they_meet: '一场志愿者活动的角落里，ENFJ在照顾每一个人，却注意到你一个人站在窗边发呆。他们走过来，不是问你怎么了，而是和你一起看窗外。', emotional_cycle: 'ENFJ用光把你引出来，你在光里待一会儿，然后开始觉得灼热。你退回去，ENFJ困惑自己做错了什么。你回来的时候带着一朵从海底捡的花，ENFJ才明白你不是在拒绝，只是需要间歇的黑暗。', conflict_source: '你觉得对方在用善意控制你，对方觉得你把好心当恶意。ENFJ想帮你融入世界，INFP想让对方理解——自己的世界本来就是完整的。', who_retreats_first: 'INFP。每次都是INFP。他们会突然变得很安静，回复消息的间隔从五分钟变成五个小时。ENFJ会反复检查自己说过的话，试图找到那句错了的话。', who_softens_first: 'ENFJ。他们会在你消失的第三天带着你喜欢的奶茶出现在你楼下，不是要你下来，只是放在那里。INFP看到那杯奶茶的时候，所有的委屈都会碎掉。', most_dangerous_phase: '当ENFJ开始觉得"我已经为你做了这么多，你为什么还是不开心"，而INFP开始觉得"你从来没有真正看见我，你只是在执行一个好人的剧本"。', deepest_connection: '一次聚会之后，所有人都走了，ENFJ终于放下那个永远在笑的表情。INFP看见了那张疲惫的脸，什么也没说，只是去倒了一杯水放在对方手边。ENFJ第一次觉得自己也被看见了。', night_state_together: 'ENFJ终于不再照顾所有人了。你们窝在沙发上，INFP在画画，ENFJ在讲今天发生的事。INFP不怎么回应，但ENFJ知道你在听——因为你偶尔会抬头笑一下。', after_separation: 'INFP会在人群中下意识寻找一个会照顾所有人的人，然后想起那个人已经不在了。ENFJ会在帮助别人的时候，突然想起那个不需要自己帮忙、只是安静陪在身边的人。' },
            en: { name: 'Night Sailor × Lighthouse Keeper', desc: 'You need to be seen, and they can see you. But be careful: when their light is too strong, you will want to retreat back into your sea.', quote: 'They are your lighthouse, but you do not need to be lit all the time.', how_they_meet: 'At a volunteer event, the ENFJ is taking care of everyone but notices you standing alone by the window, staring out. They walk over — not to ask what is wrong, but to look outside with you.', emotional_cycle: 'The ENFJ draws you out with their light. You stay in it for a while, then start to feel scorched. You pull back; the ENFJ wonders what they did wrong. When you return, you carry a flower you found at the bottom of the sea, and the ENFJ finally understands — you were not rejecting them, you just need intervals of darkness.', conflict_source: 'You feel they are using kindness to control you; they feel you are treating generosity as a threat. The ENFJ wants to help you join the world; the INFP wants them to understand — your world was already whole.', who_retreats_first: 'The INFP. Every time. Their replies go from five-minute gaps to five-hour gaps without warning. The ENFJ replays every conversation, searching for the one sentence they got wrong.', who_softens_first: 'The ENFJ. On the third day of your silence, they show up downstairs with your favorite milk tea — not asking you to come down, just leaving it there. When the INFP sees that cup, every ounce of resentment shatters.', most_dangerous_phase: 'When the ENFJ starts thinking "I have done so much for you, why are you still unhappy," and the INFP starts thinking "You never truly saw me — you were just performing the role of a good person."', deepest_connection: 'After a party, everyone has gone, and the ENFJ finally drops the smile they wear for the world. The INFP sees that tired face and says nothing — just goes to pour a glass of water and sets it beside them. For the first time, the ENFJ feels seen too.', night_state_together: 'The ENFJ has stopped taking care of everyone for the night. You curl up on the couch — the INFP drawing, the ENFJ recounting their day. The INFP barely responds, but the ENFJ knows you are listening because you look up and smile once in a while.', after_separation: 'The INFP will catch themselves scanning a crowd for the person who takes care of everyone, then remember that person is gone. The ENFJ, while helping someone else, will suddenly think of the one who never needed their help — who just stayed quietly beside them.' }
        },
        'INFP-INTJ': {
            zh: { name: '夜航者 × 静默建筑师', desc: '你用感受理解世界，对方用结构理解世界。你们会互相不理解，但也会互相补全——你教对方感受，对方教你表达。', quote: '你的柔软是对方的盲区，对方的结构是你的缺失。', how_they_meet: '在一个没什么人的深夜咖啡馆，INFP在角落写日记，INTJ在对面的桌子上画建筑草图。你们没有说话，但离开的时候INTJ在你的桌上留了一张纸条：你用的那支笔颜色很好看。', emotional_cycle: '你想要被理解，对方想要被需要。你靠近的时候，对方用逻辑回应你的情感，你觉得被推开。你退远了，对方才意识到自己又犯了同样的错误，然后笨拙地出现在你门口。', conflict_source: 'INFP觉得INTJ把感情当成需要"解决"的问题，INTJ觉得INFP的情绪波动是不可预测的变量。你想让对方感受，对方想让你解释。', who_retreats_first: 'INFP。他们不会吵，只会安静地合上笔记本，说"我没事"。INTJ知道那三个字是最不可靠的信号，但不知道该追还是该等。', who_softens_first: 'INTJ。他们不会道歉，但会在你桌上放一本他们觉得你会喜欢的书，书签夹在第47页——那是他们觉得最像你的段落。', most_dangerous_phase: '当INTJ开始把INFP的眼泪当作"又来了"的信号，而INFP开始把INTJ的沉默当作"你不在乎"的证据。两个人都在用最糟糕的方式解读对方最真实的行为。', deepest_connection: '一个普通的周二晚上，INTJ突然开口说了一件他们从来没有和任何人说过的事——不是为了寻求安慰，只是因为觉得你会懂。你没有追问细节，只是点了点头。那个点头比任何拥抱都有重量。', night_state_together: 'INTJ在桌前工作，INFP蜷在旁边的沙发上看一本很厚的小说。偶尔INFP会念一句书里的话，INTJ头也不抬地回一句"那不对"。INFP笑了，因为对方一直在听。', after_separation: 'INFP会发现自己开始用结构化的方式整理情绪，然后意识到这是对方教会自己的。INTJ会在某个建筑展上看到一件作品，心里想：那个人一定会喜欢这个。然后发现自己已经很久没有联系对方了。' },
            en: { name: 'Night Sailor × Silent Architect', desc: 'You understand the world through feeling, they through structure. You will misunderstand each other, but also complete each other — you teach them to feel, they teach you to express.', quote: 'Your softness is their blind spot; their structure is what you lack.', how_they_meet: 'A quiet late-night cafe with almost no one there. The INFP writes in a journal at one corner; the INTJ sketches building plans at the opposite table. You never speak, but when the INTJ leaves, they leave a note on your table: the color of your pen is beautiful.', emotional_cycle: 'You want to be understood; they want to be needed. You move close, and they answer your feelings with logic — you feel pushed away. You pull back, and they realize they have made the same mistake again, then show up at your door, awkward and unsure.', conflict_source: 'The INFP feels the INTJ treats emotions as problems to be solved. The INTJ feels the INFP\'s emotional waves are an unpredictable variable. You want them to feel; they want you to explain.', who_retreats_first: 'The INFP. They will not argue — just quietly close their notebook and say "I am fine." The INTJ knows those three words are the least reliable signal in the world, but cannot decide whether to follow or to wait.', who_softens_first: 'The INTJ. They will not apologize, but they will leave a book on your desk — one they think you would like — with a bookmark on page forty-seven, the passage they think sounds most like you.', most_dangerous_phase: 'When the INTJ starts reading the INFP\'s tears as "here we go again," and the INFP starts reading the INTJ\'s silence as proof that they do not care. Both are interpreting each other\'s most honest behavior in the worst possible way.', deepest_connection: 'An ordinary Tuesday night, and the INTJ suddenly says something they have never told anyone — not for comfort, but because they think you will understand. You do not press for details. You just nod. That nod weighs more than any embrace.', night_state_together: 'The INTJ works at their desk; the INFP curls up on the nearby couch with a thick novel. Occasionally the INFP reads a line aloud, and the INTJ, without looking up, says "that is wrong." The INFP smiles, because they were listening the whole time.', after_separation: 'The INFP will catch themselves organizing their feelings into a structure and realize the INTJ taught them that. The INTJ, at some architecture exhibition, will see a piece and think — that person would love this — then realize it has been months since they reached out.' }
        },
        'INFJ-ENTP': {
            zh: { name: '星图解读者 × 迷宫设计师', desc: '你想要深度，对方想要广度。你会被对方的聪明吸引，但也会被对方的不认真伤到。', quote: '你需要对方认真一点，对方需要你放松一点。', how_they_meet: '一场辩论赛的观众席上，ENTP在台上把对手绕进了一个逻辑死胡同。所有人都在笑，只有你注意到他笑的时候眼睛里有一瞬间的空洞。赛后你们聊了四个小时，从逻辑聊到了孤独。', emotional_cycle: 'ENTP用聪明把你逗笑，你用深度让他们安静。但安静久了ENTP会不安，开始用更多的玩笑填满空间。你觉得他们不认真，他们觉得你太沉重。然后某个深夜ENTP突然说了一句真话，你才知道那些玩笑下面压着什么。', conflict_source: 'INFJ需要对方在关键时刻认真，ENTP把认真当作一种暴露弱点的方式。你觉得对方在逃避，对方觉得你在要求一种他们不知道怎么给出的东西。', who_retreats_first: 'ENTP。他们不会承认自己在退缩，只会变得更加话多、更加跳跃、更加不着边际。INFJ看着对方的表演，心里很清楚——越热闹的时候，对方越害怕。', who_softens_first: 'INFJ。他们会在对方最混乱的时候安静地出现在旁边，不追问，不分析，只是在。ENTP会在某个瞬间突然安静下来，然后说一句只有你能听懂的话。', most_dangerous_phase: '当ENTP开始用玩笑来回应INFJ认真的问题，而INFJ开始用沉默来回应ENTP的玩笑。两个人都以为对方不在乎，其实两个人都在用自己最笨的方式保护自己。', deepest_connection: '一个所有人都走了的派对之后，ENTP在收拾空酒瓶，突然停下来问你："你觉得人真的能被另一个人理解吗？"你知道这个问题他们从来没有问过任何人。你没有给答案，只是坐在他们旁边的地板上，陪你一起不回答。', night_state_together: 'ENTP在厨房里煮泡面，一边煮一边给你讲一个你完全不感兴趣的新理论。你坐在餐桌上听，手里捧着一杯茶。面煮好了，ENTP先尝了一口，皱了皱眉，然后把好的那碗推给你。', after_separation: 'INFJ会在看到一个巧妙的论证时下意识想转发给对方，然后停住。ENTP会在某个深夜突然发现自己在和空气辩论一个只有你会关心的哲学问题，然后意识到自己在想念一种被看穿的感觉。' },
            en: { name: 'Star Reader × Maze Designer', desc: 'You want depth, they want breadth. You will be drawn to their cleverness, but hurt by their lack of seriousness.', quote: 'You need them to be more serious; they need you to be more relaxed.', how_they_meet: 'In the audience at a debate competition, the ENTP on stage has just cornered their opponent in a logic trap. Everyone is laughing, but only you notice a flash of emptiness in their eyes behind the grin. After the event you talk for four hours — from logic to loneliness.', emotional_cycle: 'The ENTP makes you laugh with their brilliance; you make them quiet with your depth. But silence makes the ENTP restless, so they fill the space with more jokes. You feel they are not taking things seriously; they feel you are too heavy. Then one late night the ENTP says something real, and you finally see what those jokes were sitting on top of.', conflict_source: 'The INFJ needs the ENTP to be serious at critical moments. The ENTP treats seriousness as a way of exposing weakness. You think they are running away; they think you are asking for something they do not know how to give.', who_retreats_first: 'The ENTP. They will not admit they are pulling back — they just become louder, more scattered, more tangential. The INFJ watches the performance and knows: the louder it gets, the more afraid they are.', who_softens_first: 'The INFJ. They appear quietly beside the ENTP at their most chaotic — no questions, no analysis, just presence. The ENTP will suddenly go still, then say something only the INFJ can decode.', most_dangerous_phase: 'When the ENTP starts answering the INFJ\'s serious questions with jokes, and the INFJ starts answering the ENTP\'s jokes with silence. Both think the other does not care, when both are just protecting themselves in the only way they know how.', deepest_connection: 'After a party where everyone else has gone home, the ENTP is collecting empty bottles and suddenly stops. "Do you think a person can really be understood by another person?" They have never asked anyone this. You do not answer. You just sit down on the floor beside them and share the not-answering.', night_state_together: 'The ENTP boils instant noodles in the kitchen, narrating a new theory you have zero interest in. You sit at the table listening, holding a cup of tea. The noodles are done; the ENTP tastes a mouthful, frowns, then pushes the better bowl toward you.', after_separation: 'The INFJ will see an elegant argument and instinctively want to forward it to the ENTP, then stop. The ENTP will find themselves, late one night, debating a philosophical question only the INFJ would care about — with no one — and realize they miss the feeling of being seen through.' }
        },
        'INTJ-ENTJ': {
            zh: { name: '静默建筑师 × 风暴指挥官', desc: '你们都看到三步之后，但一个在安静中规划，一个在风暴中执行。你们会成为最强的组合，但也会争夺控制权。', quote: '你们都想要控制，但最好的时刻是你们分工的时刻。', how_they_meet: '一个创业孵化器的展示日，所有人在推销自己的项目。ENTJ在台上侃侃而谈，INTJ坐在最后一排，笔记本上已经画出了对方方案里三个致命漏洞。展示结束后ENTJ径直走向你，说："你一直在皱眉，说说为什么。"', emotional_cycle: '你们合作的时候像一台精密的机器，高效、默契、无人能挡。但到了决策的分叉口，两个人都觉得自己看到了更好的路。冷战不是用沉默进行的，而是用各自做出不同的决定进行的。直到你们发现两条路通向同一个终点。', conflict_source: 'ENTJ想要速度和影响力，INTJ想要完美和远见。ENTJ觉得INTJ在拖延，INTJ觉得ENTJ在鲁莽。你们都尊重对方的能力，但不信任对方的节奏。', who_retreats_first: 'INTJ。他们不会退出，只是会开始做自己的版本。ENTJ会在会议上发现INTJ已经私下建了一个替代方案，而且那个方案更好。这既让ENTJ愤怒，又让ENTJ佩服。', who_softens_first: 'ENTJ。他们会在某个关键节点主动走进INTJ的办公室，把门关上，然后说："你的方案更好，我需要你。"对ENTJ来说，这是他们能给出的最大的示弱。INTJ听到了，但会假装在看电脑屏幕。', most_dangerous_phase: '当你们开始把对方当作竞争对手而不是合作伙伴。ENTJ在外面扩大影响力，INTJ在暗处构建替代系统。你们的战争不是用争吵进行的，而是用各自默默地赢进行的。', deepest_connection: '一次项目失败之后，所有人都在分析原因。ENTJ让所有人离开会议室，只剩下你们两个。他们关上门，靠在墙上，第一次没有说话。你也没有说话。你们在沉默中一起承受了一次失败，这比任何成功都让你们更信任对方。', night_state_together: '各自占据办公桌的一边，白板上画满了只有你们能看懂的流程图。ENTJ在打电话谈合作，INTJ在修改方案的第三版。偶尔ENTJ会捂住话筒，转头问你一个数字，你头也不抬就报出来了。', after_separation: 'INTJ会发现自己在和新团队合作的时候，下意识地留出一个位置——那个位置以前是给ENTJ的。ENTJ会在做出一个重大决定之后，突然想打电话问问那个总是能在关键时刻给出不同视角的人，然后想起你们已经不在同一个项目里了。' },
            en: { name: 'Silent Architect × Storm Commander', desc: 'You both see three steps ahead, but one plans in silence, the other executes in the storm. You will become the strongest team, but also fight for control.', quote: 'You both want control, but your best moments are when you divide the work.', how_they_meet: 'Demo day at a startup incubator. Everyone is pitching. The ENTJ is on stage, commanding the room; the INTJ sits in the last row, their notebook already mapping three fatal flaws in the plan. After the presentation the ENTJ walks straight to you and says, "You were frowning the whole time. Tell me why."', emotional_cycle: 'When you collaborate, you are a precision machine — efficient, seamless, unstoppable. But at every decision fork, each of you sees a better path. Your cold wars are not waged in silence but in each of you quietly making different calls — until you discover both roads lead to the same destination.', conflict_source: 'The ENTJ wants speed and impact; the INTJ wants perfection and foresight. The ENTJ thinks the INTJ is stalling; the INTJ thinks the ENTJ is reckless. You both respect the other\'s ability but distrust their timing.', who_retreats_first: 'The INTJ. They do not withdraw — they start building their own version. The ENTJ discovers at the next meeting that the INTJ has been privately constructing an alternative plan, and it is better. This makes the ENTJ furious and impressed at the same time.', who_softens_first: 'The ENTJ. At some critical juncture they walk into the INTJ\'s office, close the door, and say: "Your plan is better. I need you." For an ENTJ, this is the greatest act of vulnerability they can offer. The INTJ hears it but pretends to be reading something on their screen.', most_dangerous_phase: 'When you start treating each other as rivals instead of partners. The ENTJ expands influence outward; the INTJ builds an alternative system in the background. Your war is not fought with arguments but with each of you quietly winning on your own.', deepest_connection: 'After a project fails, everyone is dissecting what went wrong. The ENTJ clears the conference room until only the two of you remain. They close the door, lean against the wall, and for the first time say nothing. You say nothing too. You share a failure in silence, and it makes you trust each other more than any success ever could.', night_state_together: 'Each occupies one side of the desk. The whiteboard is covered in flowcharts only you two can read. The ENTJ is on a call negotiating a partnership; the INTJ is revising version three of the plan. Occasionally the ENTJ covers the mouthpiece, turns, and asks you for a number. You answer without looking up.', after_separation: 'The INTJ will find, while working with a new team, that they have unconsciously left a space — the space that used to belong to the ENTJ. The ENTJ, after making a major decision, will suddenly want to call the person who always offered a different angle at the critical moment, then remember you are no longer on the same project.' }
        },
        'INTP-ENFP': {
            zh: { name: '量子观察者 × 野火播种者', desc: '你的逻辑和对方的热情会碰撞出火花。你会被对方的自由吸引，对方会被你的深度吸引。但你们都需要学会完成一件事。', quote: '你们一起会开始很多事，但需要学会一起完成一件事。', how_they_meet: '一个只有五个人的深夜线上论坛，讨论一个关于"如果时间是圆形的"的帖子。ENFP在回复里写了一段诗，INTP在下面写了一段反驳，ENFP又回了一段更长的诗。你们私信了对方，聊到天亮。', emotional_cycle: 'ENFP带来新的想法和可能性，INTP把它们拆开看看里面是什么。你们会一起兴奋地开始一个新项目，然后在第三天被另一个更新的想法拐跑。这种模式让你们永远不无聊，也永远没有结果。', conflict_source: 'INTP觉得ENFP太分散，ENFP觉得INTP太挑剔。你想分析对方的热情从哪里来，对方觉得你在把他们的火苗浇灭。', who_retreats_first: 'INTP。他们会回到自己的世界里，开始研究一个新的课题，像是从来没有认识过对方一样。这不是冷漠，是他们需要重新校准自己的频率。', who_softens_first: 'ENFP。他们会在某天突然出现在你面前，带着一个你从来没有听过的故事，和一种你从来没有见过的兴奋。你还没来得及说"我们上次不欢而散"，他们已经把一个新的世界铺在你面前了。', most_dangerous_phase: '当INTP开始用逻辑反驳ENFP的每一个想法，而ENFP开始觉得对方只是在享受"赢"的感觉。你们的对话从碰撞变成了对抗，从对抗变成了沉默。', deepest_connection: '凌晨两点，你们在讨论一个没有答案的问题。ENFP说了一句完全没有逻辑但直觉上正确的话，INTP愣住了——因为他们用逻辑推导了三天才得出同样的结论。你们看着对方，第一次觉得逻辑和直觉可能是同一种语言的两种方言。', night_state_together: '你们各自缩在沙发的两头，INTP在看一篇论文，ENFP在手机上同时看三个不同的东西。偶尔ENFP会突然念出屏幕上的一句话，INTP会从论文里抬头说"那个不对"，然后开始解释为什么。ENFP其实早就知道不对，他们只是想听你解释。', after_separation: 'INTP会发现自己在遇到一个有趣的问题时，脑子里自动模拟了一段ENFP会怎么回应的对话。ENFP会在某个灵感爆发的瞬间环顾四周，想找到那个总是能把自己天马行空的想法变成现实的人，然后发现那个人不在了。' },
            en: { name: 'Quantum Observer × Wildfire Sower', desc: 'Your logic and their enthusiasm will spark. You are drawn to their freedom; they are drawn to your depth. But you both need to learn to finish one thing.', quote: 'You will start many things together, but need to learn to finish one thing together.', how_they_meet: 'A late-night online forum with five people, debating a post titled "What if time is circular." The ENFP replies with a poem; the INTP posts a rebuttal beneath it; the ENFP writes a longer poem. You DM each other and talk until dawn.', emotional_cycle: 'The ENFP brings new ideas and possibilities; the INTP takes them apart to see what is inside. You get excited together and launch a new project, then get lured away by something shinier on day three. This pattern means you are never bored — and never finished.', conflict_source: 'The INTP thinks the ENFP is too scattered; the ENFP thinks the INTP is too critical. You want to analyze where their fire comes from; they feel you are smothering the flame.', who_retreats_first: 'The INTP. They return to their own world and start researching a new subject as though you never met. It is not coldness — it is recalibration.', who_softens_first: 'The ENFP. They appear out of nowhere with a story you have never heard and an excitement you have never seen. Before you can say "we left things badly last time," they have already unfolded a new world in front of you.', most_dangerous_phase: 'When the INTP starts using logic to challenge every single idea the ENFP has, and the ENFP starts feeling the other person just enjoys winning. Your conversations shift from spark to friction, from friction to silence.', deepest_connection: 'Two in the morning, discussing a question with no answer. The ENFP says something with no logic but exactly right by instinct. The INTP goes still — they spent three days reasoning their way to the same conclusion. You look at each other and realize, for the first time, that logic and intuition might just be two dialects of the same language.', night_state_together: 'Curled at opposite ends of the couch — the INTP reading a paper, the ENFP scrolling three things on their phone at once. The ENFP reads a random line from the screen; the INTP looks up from the paper and says "that is wrong," then explains why. The ENFP already knew it was wrong. They just wanted to hear you explain it.', after_separation: 'The INTP will encounter an interesting problem and find their brain automatically simulating what the ENFP would say. The ENFP, mid-inspiration, will look around for the person who always turned their wildest ideas into something real — and find they are not there.' }
        },
        'ENFJ-ISFP': {
            zh: { name: '灯塔守望者 × 晨曦漫步者', desc: '你想照亮对方，但对方不需要被照亮——对方需要的是有人陪自己走一段安静的路。', quote: '放下你的灯，和对方一起走。', how_they_meet: '一次朋友的画展上，ISFP站在一幅画前看了二十分钟没动。ENFJ本来在招呼全场的人，但注意到那个角落里安静的身影。你走过去问"你在看什么"，对方说"在看画家没有画出来的那部分"。', emotional_cycle: 'ENFJ想照顾ISFP，ISFP用行动而不是语言来回应。你以为对方不需要你，但在某个普通的下午，ISFP递给你一杯你上次随口提过的茶。你才意识到对方一直在听，只是不会说。', conflict_source: 'ENFJ想要语言上的确认——"你爱我吗""你在乎我吗"。ISFP觉得爱不需要说，做了就够了。你需要听，他们觉得做了就够。', who_retreats_first: 'ISFP。他们不会告诉你他们要走了，只是会变得越来越安静，然后某天你发现他们已经一个人去了你不知道的地方。不是逃离，是他们需要独处来充电。', who_softens_first: 'ISFP。他们会带着一个自己做的东西回来——一幅画、一首歌、一个从路上捡回来的东西。他们不会说"对不起"，但那个东西就是他们的道歉和情书。', most_dangerous_phase: '当ENFJ开始把ISFP的沉默当作冷漠，然后变得越来越用力地付出，ISFP觉得越来越窒息。你的灯太亮了，他们需要的只是月光。', deepest_connection: '一个没有任何计划的下午，你们什么都没说就一起出了门。ISFP带你去了一个你从来不知道的地方——一家藏在巷子里的小店，或者一个只有他们知道的看日落的角落。你在那个地方第一次觉得不需要照亮任何人，只需要在。', night_state_together: 'ISFP在整理今天拍的照片，ENFJ在旁边翻一本杂志。你偶尔抬头看一眼对方的屏幕，看到一张你不知道什么时候被拍下的照片——你笑得很自然。ISFP没有说"我偷拍了你"，只是把那张照片设成了手机壁纸。', after_separation: 'ENFJ会在人群中习惯性地去照顾每一个人，然后突然觉得疲惫——因为以前有一个人不需要你的照顾，只是安静地陪在你身边。ISFP会在拍照的时候下意识地留出画面的一角，那个角度以前总是有你在。' },
            en: { name: 'Lighthouse Keeper × Dawn Walker', desc: 'You want to light their way, but they do not need to be lit — they need someone to walk a quiet path with them.', quote: 'Put down your light and walk with them.', how_they_meet: 'At a friend\'s art exhibition, the ISFP has been standing in front of one painting for twenty minutes without moving. The ENFJ is working the room but notices the quiet figure in the corner. You walk over and ask, "What are you looking at?" They say, "The part the painter did not paint."', emotional_cycle: 'The ENFJ wants to take care of the ISFP; the ISFP responds with actions, not words. You think they do not need you, but on some ordinary afternoon the ISFP hands you a cup of tea you mentioned in passing weeks ago. Only then do you realize they were listening all along — they just do not say it.', conflict_source: 'The ENFJ wants verbal confirmation — "Do you love me?" "Do you care?" The ISFP feels love does not need to be said; showing it is enough. You need to hear it; they feel doing it is enough.', who_retreats_first: 'The ISFP. They will not tell you they are leaving — they just grow quieter and quieter, and one day you discover they have gone somewhere you did not know about, alone. It is not escape. They need solitude to recharge.', who_softens_first: 'The ISFP. They come back carrying something they made — a painting, a song, something picked up on the road. They will not say "I am sorry," but that object is both their apology and their love letter.', most_dangerous_phase: 'When the ENFJ starts reading the ISFP\'s silence as indifference and pushes harder to give, the ISFP starts to suffocate. Your light is too bright; they only need moonlight.', deepest_connection: 'An unplanned afternoon. Without a word you leave the house together. The ISFP takes you somewhere you never knew existed — a tiny shop hidden in an alley, or a sunset corner only they have found. In that place you realize, for the first time, that you do not need to illuminate anyone. You just need to be there.', night_state_together: 'The ISFP sorts through photos from the day; the ENFJ flips through a magazine beside them. You glance at their screen and see a photo of yourself you did not know was taken — you are laughing naturally. The ISFP does not say "I took a candid shot of you." They just set it as their phone wallpaper.', after_separation: 'The ENFJ will find themselves caring for everyone in a crowd, then feel a sudden fatigue — because there used to be someone who did not need caring for, who just stayed quietly at your side. The ISFP, while taking photos, will leave one corner of the frame empty out of habit. That corner used to always have you in it.' }
        },
        'ESFJ-ISTP': {
            zh: { name: '春雨编织者 × 雾中探险家', desc: '你用行动表达爱，对方用沉默表达信任。你们的爱的语言不同，但都是真的。', quote: '你的温暖和对方的沉默，都是爱。', how_they_meet: '厨房里。你在做一桌菜招待朋友，对方被叫来修一个坏掉的水龙头。你递了一杯水过去，对方修完之后帮你调了一下灶台的火候——说"你的火太大了，菜会老"。你第一次遇到一个用修东西的方式关心你的人。', emotional_cycle: 'ESFJ不停地给予——做饭、关心、安排，ISTP默默地接受，偶尔修一个东西作为回报。你觉得对方不够热情，对方觉得你太累。你们都在用自己的方式说"我在乎"，但翻译器坏了。', conflict_source: 'ESFJ需要回应——一句谢谢、一个拥抱、一个肯定的眼神。ISTP觉得他们已经在用行动回应了，为什么还要说出来。你要的是话，他们给的是手。', who_retreats_first: 'ISTP。他们不会吵，只是会去车库或者工作室，开始拆一个什么东西。ESFJ站在门口看了一会儿，不知道该进去还是该走开。', who_softens_first: 'ESFJ。他们会端一碗汤或者一盘切好的水果放在对方工作台的角落，不说话，不看对方，然后默默走开。ISTP会在十五分钟后把空碗洗好放回厨房。', most_dangerous_phase: '当ESFJ开始觉得"我做了这么多，你连一句好听的话都不说"，而ISTP开始觉得"你为什么总是需要确认"。你的雨下得太大了，他们的雾需要空间。', deepest_connection: '一个你生病的雨天，ISTP没有说"你还好吗"，而是出现了。他们带来了药、一个毯子、还有一杯温度刚好的水。他们坐在你旁边，开始安静地修你一直说要修的那个抽屉。你发烧迷迷糊糊地看着他们的背影，觉得那是世界上最可靠的东西。', night_state_together: 'ESFJ在厨房里收拾晚餐的残局，ISTP在客厅的地板上修一个你不知道什么时候坏了的收音机。收音机突然响了，放的是一首老歌。ISTP没有转头，但你知道那是他们调到你提过喜欢的频道。', after_separation: 'ESFJ会在做饭的时候习惯性地多做一份，然后想起来已经没有人吃了。ISTP会在修好一个东西之后，下意识地想告诉那个总是有东西要修的人，然后发现那个人已经不在了。' },
            en: { name: 'Spring Rain Weaver × Fog Explorer', desc: 'You express love through action, they express trust through silence. Your love languages differ, but both are real.', quote: 'Your warmth and their silence are both love.', how_they_meet: 'The kitchen. You are cooking a dinner for friends; they were called in to fix a broken faucet. You hand them a glass of water. When they finish the repair, they adjust the flame on your stove and say, "Your heat is too high — the food will toughen." It is the first time someone has cared for you by fixing things.', emotional_cycle: 'The ESFJ keeps giving — cooking, caring, arranging. The ISTP accepts quietly and occasionally fixes something in return. You think they are not warm enough; they think you are exhausting yourself. You are both saying "I care" in your own way, but the translator is broken.', conflict_source: 'The ESFJ needs a response — a thank-you, a hug, a look that says yes. The ISTP feels they have already responded through action, so why must it also be said. You want words; they give hands.', who_retreats_first: 'The ISTP. They will not argue — they just go to the garage or the workshop and start taking something apart. The ESFJ stands in the doorway watching, unsure whether to walk in or walk away.', who_softens_first: 'The ESFJ. They bring a bowl of soup or a plate of sliced fruit to the corner of the workbench without a word, without looking, then quietly leave. Fifteen minutes later the ISTP has washed the empty bowl and returned it to the kitchen.', most_dangerous_phase: 'When the ESFJ starts thinking "I have done so much and you cannot even say one nice thing," and the ISTP starts thinking "why do you always need confirmation." Your rain is falling too hard; their fog needs space.', deepest_connection: 'A rainy day when you are sick. The ISTP does not say "are you okay" — they just show up. They bring medicine, a blanket, and a glass of water at exactly the right temperature. They sit beside you and start quietly fixing the drawer you have been meaning to fix for months. You watch their back through a fever haze and think it is the most reliable thing in the world.', night_state_together: 'The ESFJ cleans up dinner in the kitchen; the ISTP sits on the living room floor fixing a radio you did not know was broken. The radio suddenly crackles to life with an old song. The ISTP does not turn around, but you know they tuned it to the station you once mentioned you liked.', after_separation: 'The ESFJ will instinctively cook an extra portion, then remember there is no one to eat it. The ISTP, after fixing something, will want to tell the person who always had something that needed fixing — then realize that person is gone.' }
        },
        'ENFP-ISTJ': {
            zh: { name: '野火播种者 × 古卷守护者', desc: '你想要自由，对方想要稳定。但你会成为对方生活中的一阵风，对方会成为你回来的理由。', quote: '你是对方生活中的一阵风，对方是你回来的理由。', how_they_meet: '你迷路了。在一个你不熟悉的城市，你对着地图乱走，对方是那个被你拦下来问路的人。他们不仅给你指了路，还带你走了一段，因为你看起来实在太容易走丢了。你发现他们走路的节奏很稳，像一首你知道所有歌词的歌。', emotional_cycle: 'ENFP带来变化和惊喜，ISTJ在变化中守住不变的东西。你会觉得对方太死板，对方会觉得你太不稳定。但当生活真的变得一团糟的时候，你是那个乱跑的人，对方是那个给你留着一盏灯的人。', conflict_source: '你觉得对方的生活像一个没有出口的房间，对方觉得你的生活像一个没有墙壁的房子。你想要对方和你一起飞，对方想要你和他们一起落地。', who_retreats_first: 'ENFP。他们会突然变得很忙——忙着去见新的人、去新的地方、开始新的事情。ISTJ不会追，只是把你的那副碗筷留在柜子里原来的位置。', who_softens_first: 'ENFP。他们会在某个晚上突然出现在ISTJ的门口，带着一个在外地买的冰箱贴或者一袋对方没吃过的零食。ISTJ会假装不惊喜，但第二天你会发现那个冰箱贴已经出现在冰箱上了。', most_dangerous_phase: '当ISTJ开始把ENFP的每一次出发都当作抛弃，而ENFP开始把ISTJ的每一次挽留都当作束缚。你飞得越远，对方把门关得越紧。', deepest_connection: '一个普通的周三晚上，你在外面跑了一整天，回到ISTJ的家。你累得不想说话，对方也没有问你去了哪里。他们只是把你上次忘在这里的那件洗好的衣服叠好放在沙发上，然后去厨房热了一碗汤。你喝着那碗汤，觉得这是你所有冒险的终点。', night_state_together: '你在沙发上讲今天遇到的有趣的人和事，ISTJ在旁边一边听一边在笔记本上写明天的待办事项。你讲到一半发现对方在写东西，假装生气，对方头也不抬地说"我在听，你继续"。然后准确地复述了你刚才说的最后一句话。', after_separation: 'ENFP会在某个陌生城市经过一家和你们一起去过的店很像的店，然后在门口站了很久。ISTJ会在整理东西的时候翻到你留下的一个小物件，把它放回原处，好像你随时会回来取一样。' },
            en: { name: 'Wildfire Sower × Ancient Scroll Keeper', desc: 'You want freedom, they want stability. But you become a gust of wind in their life, and they become your reason to return.', quote: 'You are a gust of wind in their life; they are your reason to return.', how_they_meet: 'You are lost. In an unfamiliar city, wandering with a bad map, you stop the first person who looks like they know where they are going. They not only give you directions but walk you part of the way, because you clearly cannot be trusted to arrive on your own. You notice their pace is steady, like a song whose lyrics you already know.', emotional_cycle: 'The ENFP brings change and surprise; the ISTJ holds steady through every shift. You think they are too rigid; they think you are too unstable. But when life actually falls apart, you are the one running in circles and they are the one who left a light on for you.', conflict_source: 'You feel their life is a room with no exits; they feel yours is a house with no walls. You want them to fly with you; they want you to land with them.', who_retreats_first: 'The ENFP. You suddenly become very busy — new people, new places, new projects. The ISTJ does not chase you. They just leave your chopsticks in their usual spot in the cabinet.', who_softens_first: 'The ENFP. You show up at the ISTJ\'s door one evening with a fridge magnet from your trip or a snack they have never tried. The ISTJ pretends not to be surprised, but the next day the magnet is already on the fridge.', most_dangerous_phase: 'When the ISTJ starts reading every departure as abandonment, and the ENFP starts reading every attempt to hold on as a cage. The farther you fly, the tighter they shut the door.', deepest_connection: 'An ordinary Wednesday night. You have been out all day and come back to the ISTJ\'s place too tired to talk. They do not ask where you were. They just fold the shirt you left behind last time — freshly washed — and set it on the couch, then go heat up a bowl of soup. You drink that soup and feel, for once, that this is where all your adventures end.', night_state_together: 'You sprawl on the couch describing the interesting people and things you encountered today. The ISTJ listens and writes tomorrow\'s to-do list in a notebook at the same time. You pause mid-sentence and accuse them of not listening. Without looking up, they recite your last sentence word for word.', after_separation: 'The ENFP will pass a shop in some strange city that looks exactly like one you visited together, and stand outside for a long time. The ISTJ, while tidying up, will find a small thing you left behind and put it back where it was — as though you might come for it any day now.' }
        },
        'ESTP-ISFJ': {
            zh: { name: '追风者 × 温室守护者', desc: '你活在当下，对方活在细节里。你会觉得对方太小心翼翼，对方会觉得你太不顾后果。但你们都需要对方。', quote: '你需要对方让你慢下来，对方需要你让对方活起来。', how_they_meet: '一个户外市集上，你在试吃摊位前一口气尝了六种辣酱，辣得眼泪都出来了。ISFJ在旁边的摊位买手工肥皂，看到你的样子忍不住笑出来。你递了一块辣酱饼干过去，对方犹豫了一下接了，然后也被辣到了。你们一起灌了三瓶水。', emotional_cycle: 'ESTP带ISFJ去看他们从来不会自己去看的世界，ISFJ在那个世界里给ESTP留了一条回家的路。你觉得对方太保守，对方觉得你太鲁莽。但每次你冲得太快的时候，身后总有一个人在帮你收尾。', conflict_source: 'ESTP想现在就去，ISFJ想先计划好。你觉得对方在限制你，对方觉得你在无视风险。你要的是自由，对方要的是安全。', who_retreats_first: 'ESTP。他们会直接去做自己想做的事，不是赌气，只是他们处理冲突的方式是行动而不是讨论。ISFJ会一个人坐在家里，把你上次弄坏的那个东西修好。', who_softens_first: 'ESTP。他们会带着一种奇怪的礼物回来——一块从山上捡的石头，或者一个你根本用不上的小工具。他们不会说"对不起"，但会说"这个很适合你"。ISFJ会把那个没用的东西放在床头柜上。', most_dangerous_phase: '当ESTP开始觉得ISFJ是自己人生的刹车而不是方向盘，而ISFJ开始觉得自己在一段关系里只是在善后。你飞得太快了，对方已经累了。', deepest_connection: '一次你受伤之后——不是什么大事，就是从自行车上摔了一下——ISFJ没有说"我早就说了"，只是蹲下来，用一种你从来没见过的认真帮你处理伤口。你看着他们低着头的样子，第一次觉得有人在乎你是不是安全的。', night_state_together: '你趴在沙发上看手机上一个极限运动的视频，ISFJ在旁边的桌子上给植物浇水。你把手机举到对方面前说"你看这个！"ISFJ看了一眼说"你会死的"，然后继续浇水。你笑了，因为你知道那是他们说"我爱你"的方式。', after_separation: 'ESTP会在做一件危险的事之前习惯性地想"有人会骂我"，然后发现那个会骂你的人已经不在了。ISFJ会在家里发现你上次忘在这里的一件外套，叠好放进衣柜最里面，和其他不再穿的衣服放在一起。' },
            en: { name: 'Wind Chaser × Greenhouse Guardian', desc: 'You live in the moment, they live in the details. You will think they are too careful; they will think you are too reckless. But you need each other.', quote: 'You need them to slow you down; they need you to bring them to life.', how_they_meet: 'An outdoor market. You are sampling six hot sauces in a row at a tasting booth, eyes streaming from the heat. The ISFJ, buying handmade soap at the next stall, cannot help laughing at you. You hold out a hot-sauce cracker; they hesitate, take a bite, and start tearing up too. You both chug three bottles of water together.', emotional_cycle: 'The ESTP shows the ISFJ a world they would never enter alone; the ISFJ leaves a path home in that world for the ESTP. You think they are too cautious; they think you are too reckless. But every time you charge ahead too fast, someone behind you is cleaning up.', conflict_source: 'The ESTP wants to go now; the ISFJ wants to plan first. You feel they are holding you back; they feel you are ignoring the danger. You want freedom; they want safety.', who_retreats_first: 'The ESTP. You go do what you wanted to do — not out of spite, but because your way of handling conflict is action, not discussion. The ISFJ stays home alone and fixes the thing you broke last time.', who_softens_first: 'The ESTP. You come back with a strange gift — a rock you found on a mountain, or some small tool they will never use. You do not say "I am sorry." You say "this suits you." The ISFJ puts the useless thing on the nightstand.', most_dangerous_phase: 'When the ESTP starts seeing the ISFJ as the brake on their life rather than the steering wheel, and the ISFJ starts feeling they are only in this relationship to clean up after someone. You are flying too fast; they are getting tired.', deepest_connection: 'After you get hurt — nothing serious, just a fall off your bike — the ISFJ does not say "I told you so." They just kneel down and tend to your wound with a seriousness you have never seen from them before. Watching them bent over your scraped knee, you feel for the first time that someone cares whether you are safe.', night_state_together: 'You are sprawled on the couch watching an extreme sports video on your phone. The ISFJ waters the plants at the table nearby. You shove the phone in their face: "Look at this!" The ISFJ glances and says "you would die," then goes back to watering. You laugh, because you know that is how they say "I love you."', after_separation: 'The ESTP will be about to do something dangerous and instinctively think "someone is going to yell at me," then realize the person who would yell is gone. The ISFJ will find a jacket you left behind, fold it, and place it in the back of the closet with the clothes no one wears anymore.' }
        },
        'ENTP-INFJ': {
            zh: { name: '迷宫设计师 × 星图解读者', desc: '你会被对方的深度吸引，对方会被你的聪明吸引。但你要认真——对方能看穿你的玩笑背后是什么。', quote: '对方能看穿你，这让你既害怕又安心。', how_they_meet: '一个聚会上，你在用一个不可能的角度论证"猫是液体"，所有人都在笑。INFJ没有笑，他们看着你的眼睛说了一句"你今天不太开心吧"。你愣了一下，然后笑得更大声了。对方没有追问，但你知道自己被看穿了。', emotional_cycle: 'ENTP用聪明和幽默把世界变得有趣，INFJ在那些玩笑里找到了通往你内心的入口。你躲，他们等。你再躲，他们还是等。直到有一天你累了，回头发现他们一直站在同一个地方。', conflict_source: 'ENTP把真诚当作弱点，INFJ把真诚当作关系的基础。你需要空间来保护自己，对方需要你放下防备。你想赢，对方想要连接。', who_retreats_first: 'ENTP。他们会把所有认真的对话变成一场辩论，用三倍的语速和五倍的逻辑把对方绕进去。INFJ会安静地看着你表演，等你停下来。你知道他们在等，但你不知道怎么停下来。', who_softens_first: 'INFJ。他们会在你最混乱的时候找到你，不追问发生了什么，只是说"我在"。那两个字比任何辩论都有力，因为你知道那不是一种策略——是一种承诺。', most_dangerous_phase: '当ENTP开始把INFJ的每一次靠近都当作一种攻击，而INFJ开始把ENTP的每一次玩笑都当作一种逃避。你们之间的迷宫变得越来越复杂，出口越来越远。', deepest_connection: '一个你输了的辩论之后，你坐在空荡荡的房间里复盘。INFJ走进来，没有说"你还好吗"，而是说"你刚才那个论点其实有道理，只是表达的方式不对"。你知道那是他们在帮你，但不是用你害怕的方式。', night_state_together: '你在厨房里煮咖啡，一边煮一边和INFJ讨论一个你今天在网上看到的离谱理论。INFJ坐在吧台后面，手里捧着一杯你十分钟前煮的已经凉了的咖啡。你说"你怎么不喝"，对方说"我在听你说话，忘了喝"。', after_separation: 'ENTP会在赢得一场辩论之后，突然觉得空虚——因为以前有一个人会在你赢了之后安静地看着你，然后说一句让整个胜利都变轻了的话。INFJ会在深夜想起那些你用玩笑保护自己的瞬间，然后希望自己当时再坚持一下。' },
            en: { name: 'Maze Designer × Star Reader', desc: 'You are drawn to their depth; they are drawn to your cleverness. But be serious — they can see what is behind your jokes.', quote: 'They can see through you, which both frightens and comforts you.', how_they_meet: 'At a party, you are delivering an elaborate argument that cats are liquid. Everyone is laughing. The INFJ is not laughing. They look at you and say, "You are not okay today." You freeze for a beat, then laugh even louder. They do not press, but you know you have been seen through.', emotional_cycle: 'The ENTP makes the world interesting with wit and humor; the INFJ finds the door to your heart hidden inside those jokes. You run; they wait. You run again; they still wait. Until one day you are tired, and you look back, and they are standing in the same spot.', conflict_source: 'The ENTP treats sincerity as weakness; the INFJ treats sincerity as the foundation of a relationship. You need space to protect yourself; they need you to let your guard down. You want to win; they want to connect.', who_retreats_first: 'The ENTP. You turn every serious conversation into a debate, using triple the speed and five times the logic to tie them in knots. The INFJ watches you perform and waits for you to stop. You know they are waiting, but you do not know how to stop.', who_softens_first: 'The INFJ. They find you at your most chaotic and do not ask what happened. They just say "I am here." Those two words carry more weight than any debate, because you know it is not a strategy — it is a promise.', most_dangerous_phase: 'When the ENTP starts reading every approach from the INFJ as an attack, and the INFJ starts reading every joke as an escape. The maze between you grows more complex, and the exit keeps moving farther away.', deepest_connection: 'After you lose a debate, you sit in an empty room replaying it. The INFJ walks in and does not say "are you okay." They say, "your point actually had merit — the delivery was just off." You know they are helping you, but not in the way you are afraid of.', night_state_together: 'You are making coffee in the kitchen, narrating a wild theory you found online. The INFJ sits on the other side of the counter holding a cup of coffee you made ten minutes ago — now cold. You say, "Why aren\'t you drinking it?" They say, "I was listening to you. I forgot."', after_separation: 'The ENTP will win a debate and feel unexpectedly hollow — because there used to be someone who watched you win in silence, then said one sentence that made the whole victory feel lighter. The INFJ will think late at night about the moments when you used jokes to protect yourself, and wish they had held on a little longer.' }
        },
        'ISTP-ESTP': {
            zh: { name: '雾中探险家 × 追风者', desc: '你们都相信行动胜于语言。一起冒险时，你们不需要说话——但也要学会在安静中陪伴。', quote: '你们的默契在行动中，但也要学会在沉默中陪伴。' },
            en: { name: 'Fog Explorer × Wind Chaser', desc: 'You both believe action speaks louder than words. When adventuring together, you do not need to talk — but learn to be present in silence too.', quote: 'Your chemistry is in action, but learn to be present in silence too.' }
        },
        'ISFP-ENFP': {
            zh: { name: '晨曦漫步者 × 野火播种者', desc: '你安静地感受世界，对方热烈地探索世界。你会被对方的勇气吸引，对方会被你的温柔吸引。', quote: '你的温柔是对方的避风港，对方的勇气是你的翅膀。' },
            en: { name: 'Dawn Walker × Wildfire Sower', desc: 'You quietly feel the world; they passionately explore it. You are drawn to their courage; they are drawn to your gentleness.', quote: 'Your gentleness is their safe harbor; their courage is your wings.' }
        },
        'INTJ-INFP': {
            zh: { name: '静默建筑师 × 夜航者', desc: '你用结构理解世界，对方用感受理解世界。你会想"解决"对方的情绪，但对方需要的不是解决方案——是陪伴。', quote: '对方不需要你的方案，只需要你在。' },
            en: { name: 'Silent Architect × Night Sailor', desc: 'You understand the world through structure; they understand through feeling. You will want to "fix" their emotions, but they do not need a solution — they need your presence.', quote: 'They do not need your plan — they just need you there.' }
        },
        'ESFP-INTJ': {
            zh: { name: '旅行说书人 × 静默建筑师', desc: '你是对方生活中的一束光，对方是你停下来的理由。你们会互相不理解，但也会互相改变。', quote: '你教对方活在当下，对方教你思考未来。' },
            en: { name: 'Traveling Storyteller × Silent Architect', desc: 'You are a beam of light in their life; they are your reason to stop. You will misunderstand each other, but also change each other.', quote: 'You teach them to live in the moment; they teach you to think about the future.' }
        }
    },

    /**
     * Get compatibility data for two MBTI types
     * @param {string} type1 - First MBTI type (e.g., 'INFP')
     * @param {string} type2 - Second MBTI type (e.g., 'INTJ')
     * @param {string} lang - Language ('zh' or 'en')
     * @returns {object|null} Compatibility data
     */
    getCompatibility: function(type1, type2, lang) {
        if (!type1 || !type2) return null;
        lang = lang || 'zh';

        // Check specific pairs (both orders)
        var pairKey1 = type1 + '-' + type2;
        var pairKey2 = type2 + '-' + type1;
        var pair = this.pairs[pairKey1] || this.pairs[pairKey2];

        // Get world mapping from MBTI_TEST archetypes
        var world1 = this.getWorld(type1);
        var world2 = this.getWorld(type2);

        // Check world-level compatibility
        var worldKey1 = world1 + '-' + world2;
        var worldKey2 = world2 + '-' + world1;
        var worldCompat = this.worlds[worldKey1] || this.worlds[worldKey2];

        if (pair && pair[lang]) {
            return {
                type: 'specific',
                name: pair[lang].name,
                desc: pair[lang].desc,
                quote: pair[lang].quote,
                world1: world1,
                world2: world2
            };
        }

        if (worldCompat && worldCompat[lang]) {
            return {
                type: 'world',
                name: worldCompat[lang].name,
                desc: worldCompat[lang].desc,
                tension: worldCompat[lang].tension,
                world1: world1,
                world2: world2
            };
        }

        // Fallback: generate generic
        return {
            type: 'generic',
            name: lang === 'zh' ? '未知连接' : 'Unknown Connection',
            desc: lang === 'zh'
                ? '每一种人格的相遇都是一种可能性。你们之间的故事，还没有被书写。'
                : 'Every meeting of personalities is a possibility. The story between you has not yet been written.',
            world1: world1,
            world2: world2
        };
    },

    /**
     * Get world for an MBTI type
     */
    getWorld: function(type) {
        if (typeof MBTI_TEST !== 'undefined' && MBTI_TEST.archetypes && MBTI_TEST.archetypes[type]) {
            return MBTI_TEST.archetypes[type].world;
        }
        // Fallback mapping
        var mapping = {
            INFP: 'dreamers', INFJ: 'dreamers', ISFP: 'dreamers', ISFJ: 'dreamers',
            INTJ: 'analysts', INTP: 'analysts', ENTJ: 'analysts', ENTP: 'analysts',
            ENFJ: 'connectors', ESFJ: 'connectors', ENFP: 'connectors', ESFP: 'connectors',
            ISTP: 'explorers', ESTP: 'explorers', ISTJ: 'explorers', ESTJ: 'explorers'
        };
        return mapping[type] || 'unknown';
    },

    /**
     * Get all types in a world
     */
    getTypesInWorld: function(world) {
        var mapping = {
            dreamers: ['INFP', 'INFJ', 'ISFP', 'ISFJ'],
            analysts: ['INTJ', 'INTP', 'ENTJ', 'ENTP'],
            connectors: ['ENFJ', 'ESFJ', 'ENFP', 'ESFP'],
            explorers: ['ISTP', 'ESTP', 'ISTJ', 'ESTJ']
        };
        return mapping[world] || [];
    }
};


// Exports
export const WORLDS_COMPAT = ARCHETYPE_COMPATIBILITY.worlds;
export const PAIRS_COMPAT = ARCHETYPE_COMPATIBILITY.pairs;

export const MBTI_TYPES = [
  "INTJ", "INTP", "ENTJ", "ENTP",
  "INFJ", "INFP", "ENFJ", "ENFP",
  "ISTJ", "ISFJ", "ESTJ", "ESFJ",
  "ISTP", "ISFP", "ESTP", "ESFP"
];

export const MBTI_GROUPS = [
  { label: "分析师", labelEn: "Analysts", types: ["INTJ", "INTP", "ENTJ", "ENTP"], color: "#4A6FA5" },
  { label: "外交官", labelEn: "Diplomats", types: ["INFJ", "INFP", "ENFJ", "ENFP"], color: "#6B5B95" },
  { label: "守护者", labelEn: "Sentinels", types: ["ISTJ", "ISFJ", "ESTJ", "ESFJ"], color: "#4A8B5A" },
  { label: "探险家", labelEn: "Explorers", types: ["ISTP", "ISFP", "ESTP", "ESFP"], color: "#C4783C" },
];

export function getWorldForType(mbtiType: string): string {
  const mapping: Record<string, string> = {
    INTJ: "analysts", INTP: "analysts", ENTJ: "analysts", ENTP: "analysts",
    INFJ: "dreamers", INFP: "dreamers", ENFJ: "connectors", ENFP: "connectors",
    ISTJ: "explorers", ISFJ: "connectors", ESTJ: "explorers", ESFJ: "connectors",
    ISTP: "explorers", ISFP: "dreamers", ESTP: "explorers", ESFP: "explorers",
  };
  return mapping[mbtiType] ?? "analysts";
}

export function getCompatibility(type1: string, type2: string, lang: "zh" | "en" = "zh") {
  const pair = PAIRS_COMPAT[`${type1}-${type2}`] ?? PAIRS_COMPAT[`${type2}-${type1}`];
  const world1 = getWorldForType(type1);
  const world2 = getWorldForType(type2);
  const world = WORLDS_COMPAT[`${world1}-${world2}`] ?? WORLDS_COMPAT[`${world2}-${world1}`];

  if (pair && pair[lang]) {
    return { pair: pair[lang], world: world?.[lang] ?? null, type1, type2 };
  }
  if (world && world[lang]) {
    return { pair: { name: world[lang].name, desc: world[lang].desc, quote: "" }, world: world[lang], type1, type2 };
  }
  return null;
}
